esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// pgrst_db_pool_timeouts_total is a counter; INCREASE() gives how many timeouts actually
// happened inside the window (the dashboard charts the same metric as a per-second rate).
// pool_waiting and pool_available are gauges, carried here as diagnostic context.
| STATS
    `Pool Timeouts` = SUM(INCREASE(pgrst_db_pool_timeouts_total)),
    `Pool Waiting` = MAX(MAX_OVER_TIME(pgrst_db_pool_waiting)),
    `Pool Available` = MIN(MIN_OVER_TIME(pgrst_db_pool_available))
  BY resource.attributes.supabase_project_ref
// Any timeout is a failed API request. Raise if your clients retry transparently.
| WHERE `Pool Timeouts` > 0
| SORT `Pool Timeouts` DESC
